diff:
--- a/training/level-1/L1-031-checklist/generateChecklist.mjs
+++ b/training/level-1/L1-031-checklist/generateChecklist.mjs
@@ -0,0 +1,56 @@
+function generateChecklist(items, options) {
+  const opts = {
+    allowOptional: options?.allowOptional ?? true
+  };
+
+  const normalizedItems = items.map((item, index) => {
+    if (typeof item === 'string') {
+      return {
+        text: item.trim().replace(/\s+/g, ' '),
+        required: true,
+        done: false,
+        id: `item-${index + 1}`
+      };
+    } else if (typeof item === 'object' && item !== null) {
+      const { id, text, required, done } = item;
+      if (!text || typeof text !== 'string') {
+        throw new Error('Invalid item: text is required and must be a string');
+      }
+      const normalizedText = text.trim().replace(/\s+/g, ' ');
+      if (normalizedText === '') {
+        throw new Error('Invalid item: text cannot be empty after normalization');
+      }
+      return {
+        id: id ?? `item-${index + 1}`,
+        text: normalizedText,
+        required: required ?? true,
+        done: done ?? false
+      };
+    } else {
+      throw new Error('Invalid item: must be a string or plain object');
+    }
+  });
+
+  const seenIds = new Set();
+  const filteredItems = normalizedItems.filter((item) => {
+    if (seenIds.has(item.id)) {
+      return false;
+    }
+    seenIds.add(item.id);
+    return true;
+  });
+
+  const finalItems = filteredItems.map((item) => {
+    if (!opts.allowOptional && !item.required) {
+      return false;
+    }
+    return item;
+  }).filter(Boolean);
+
+  return Object.freeze(finalItems.map(item => Object.freeze({
+    id: item.id,
+    text: item.text,
+    required: Boolean(item.required),
+    done: Boolean(item.done)
+  })));
+}

